using System;
using System.Text;
using UnityEngine;
using LWS.TruckBowling;
using LWS.TruckSports;
using LWS.TruckFareFight;
namespace LWS.TruckAvalancheEscape
{
 public sealed class AvalancheMatch:SportsEventSession
 {
  public Transform burialsRoot;public Transform[] burialMounds=Array.Empty<Transform>();public AvalancheWorld world;public AvalancheFront front;public SportsEventTruck[] trucks;public SportsFragmentRig[] fragments;public SportsDrivingViews drivingViews;public SportsEventCamera broadcast;public SportsCameraFit framing;public SportsChaosWeather atmosphere;public SportsRecordedReview review;public AvalancheRules rules=new AvalancheRules();public float burialGrace=4.5f;public int PhysicalSnowContacts{get;private set;}public int ActualBurials{get;private set;}public int ActualEscapes{get;private set;}
  public override string Title=>"TRUCK AVALANCHE ESCAPE";public override int MinimumPlayers=>1;public override int MaximumPlayers=>12;public override int OptionCount=>3;public override int WeatherCount=>1;public override int CompactScoreColumns=>12;public override bool SupportsSplitAIViews=>true;public override bool SupportsRaceCountdown=>true;public override float RaceCountdownSeconds=>rules.Phase==AvalanchePhase.Countdown?rules.Countdown:-1;public override float RaceStartSeconds=>rules.Phase==AvalanchePhase.Racing?rules.Clock:-1;public override bool ReplayControls=>review!=null&&review.Playing;
  public override bool MultiViewHUD=>!ReplayControls&&drivingViews!=null&&drivingViews.rally.Humans>1;
  public override bool ParticipantLocked(int slot)=>slot>=0&&slot<setup.count&&(!rules.alive[slot]||rules.finished[slot]);
  public override float ParticipantProgress(int slot)=>slot>=0&&slot<setup.count?rules.distance[slot]/world.length:-1;
  public override string ViewText(int view){int i=drivingViews.rally.owners[view];var t=trucks[i];string state=rules.finished[i]?"FINISHED · WATCHING THE RACE":!rules.alive[i]?"OUT · SPECTATING":rules.caughtFor[i]>0?"ESCAPE! "+Mathf.Max(0,burialGrace-rules.caughtFor[i]).ToString("F1")+"s TO BURIAL":"RACING · "+Mathf.Max(0,world.length-rules.distance[i]).ToString("F0")+"m TO RESCUE";return setup.players[i].name+" · "+state+"\n"+(t.body.linearVelocity.magnitude*2.23694f).ToString("F0")+" MPH · "+rules.Clock.ToString("F1")+"s · SNOW "+((t.body.position.z-front.CurrentZ)*3.28084f).ToString("F0")+"ft BEHIND\n"+ControlCaption(i);}
  public override string OptionLabel=>new[]{"STANDARD SNOW FRONT","QUICKENING AVALANCHE","RELENTLESS MOUNTAIN"}[option];public override string Header=>Title+" · "+rules.Clock.ToString("F1")+"s · AVALANCHE "+front.CurrentZ.ToString("F0")+"m";public override string Status=>rules.Phase==AvalanchePhase.Countdown?"STAY GROUNDED · CHOOSE YOUR WAY DOWN":announcementUntil>rules.Clock?announcement:"SNOW CONTACT PUSHES FIRST · ESCAPE BEFORE BURIAL · DANGER SHORTCUTS OR SAFER ROAD";
  public override string Help=>"Twelve full NWH trucks race through a giant Arctic mountain valley while a genuine moving snow front and rolling debris pursue them. Choose the broad winding safer road or risky cliff, ravine and ice-bridge shortcuts. Initial real snow contact pushes and obscures your truck; you have a configurable4.5second escape window before burial. Accelerate out and exposure recedes. Placement uses actual full-body finish time; eliminated trucks rank by distance survived. Other racers continue after the leader finishes. Drive, brake, horn, chase/cab/elevated cameras, free look, pause/reconnect, selected weather, results, recorded highlights and rematch use the collection controls. Hold ACTION to recover only when overturned/stuck on the course; recovery places you behind your current progress and never removes snow exposure. AI drives real routes, chooses risk by difficulty and recovers through the same rules. Normal snow/ice traction and gravity remain active.";
  public override bool TryReadScoreCard(int i,out string value,out string detail){value=rules.finished[i]?rules.finishTime[i].ToString("F1")+"s":rules.distance[i].ToString("F0")+"m";detail=rules.finished[i]?"FIN #"+rules.Place(i):!rules.alive[i]?"OUT":rules.caughtFor[i]>0?"ESC "+Mathf.Max(0,burialGrace-rules.caughtFor[i]).ToString("F1")+"s":"RACING";return i<setup.count;}
  readonly StringBuilder text=new StringBuilder(1000);public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append('#').Append(rules.Place(i)).Append(' ').Append(setup.players[i].name).Append(" · ").Append(rules.finished[i]?rules.finishTime[i].ToString("F2")+"s":rules.distance[i].ToString("F0")+"m · "+rules.reason[i]).AppendLine();return text.ToString();}}public override string Results=>"MOUNTAIN ESCAPE RESULTS\n\n"+Standings;
  readonly FareFightRoute[] drivers=new FareFightRoute[12];readonly int[] route=new int[12],segment=new int[12];readonly float[] lastSnow=new float[12],recoverAt=new float[12],stuckFor=new float[12];readonly Vector3[] previous=new Vector3[12];readonly float[] previousRear=new float[12];readonly bool[] wasCaught=new bool[12];float announcementUntil;string announcement="";
  protected override void BeginGame()
  {
   announcement="";announcementUntil=0;feedback.StopAll();foreach(var mound in burialMounds)mound.localScale=Vector3.zero;rules.Reset(setup.count,world.length,burialGrace,300);rules.Begin();PhysicalSnowContacts=ActualBurials=ActualEscapes=0;front.speed=new[]{12f,14,16}[option];front.ResetFront();
   if(review==null){review=gameObject.AddComponent<SportsRecordedReview>();review.match=this;review.trucks=trucks;review.fragments=fragments;review.drivingViews=drivingViews;review.broadcast=broadcast;review.framing=framing;review.atmosphere=atmosphere;review.watchAction="watchavalanche";review.extras=new[]{front.transform,front.debrisGroup,burialsRoot};}review.ResetRecord();
   for(int i=0;i<trucks.Length;i++){trucks[i].gameObject.SetActive(i<setup.count);fragments[i].ResetBody();if(i>=setup.count)continue;trucks[i].tractorMotor.Configure();trucks[i].GetComponent<NWH.VehiclePhysics2.Damage.DamageHandler>()?.Repair();trucks[i].Prepare(world.starts[i],world.startRotations[i]);drivers[i]??=new FareFightRoute();drivers[i].Reset();drivers[i].speedScale=1.45f;route[i]=setup.players[i].difficulty==BowlingDifficulty.Hard?i%world.routes.Length:0;segment[i]=0;lastSnow[i]=-100;stuckFor[i]=recoverAt[i]=0;wasCaught[i]=false;previous[i]=trucks[i].body.position;previousRear[i]=BodyRear(trucks[i]);Hold(trucks[i]);}Physics.SyncTransforms();drivingViews.Layout();atmosphere.Configure(Environment.TickCount,0,1);
  }
  static float BodyRear(SportsEventTruck t){float min=float.PositiveInfinity;foreach(var c in t.GetComponentsInChildren<Collider>())if(c.enabled&&!c.isTrigger&&c.attachedRigidbody==t.body)min=Mathf.Min(min,c.bounds.min.z);return min;}
  static void Hold(SportsEventTruck t){t.TickDrive(Vector2.zero);var input=t.tractorMotor.vehicle.input;input.states.handbrake=input.states.handbrakeRaw=1;}
  public void ContactSnow(int slot){if(!Live||rules.Phase!=AvalanchePhase.Racing||slot<0||slot>=setup.count||!rules.alive[slot]||rules.finished[slot])return;lastSnow[slot]=Time.fixedTime;PhysicalSnowContacts++;}
  protected override void Simulate(float dt)
  {
   float before=rules.Clock;rules.Tick(dt);if(rules.Complete){EndMatch();return;}bool racing=rules.Phase==AvalanchePhase.Racing;front.Step(rules.Clock,racing);atmosphere.Tick(rules.Clock);review.Capture(rules.Clock+3-rules.Countdown);
   for(int i=0;i<setup.count;i++)
   {
    var t=trucks[i];if(!racing||!rules.alive[i]||rules.finished[i]){Hold(t);continue;}bool caught=Time.fixedTime-lastSnow[i]<=Time.fixedDeltaTime*2.5f;
    if(caught){t.body.AddForce(Vector3.forward*6+Vector3.up*.4f,ForceMode.Acceleration);if(!wasCaught[i])Announce(setup.players[i].name+" CAUGHT · ACCELERATE OUT!");}
    else if(wasCaught[i]){ActualEscapes++;Announce(setup.players[i].name+" BROKE FREE!");}wasCaught[i]=caught;
    if(rules.SnowContact(i,dt,caught)){ActualBurials++;t.Power(false);t.body.linearVelocity=t.body.angularVelocity=Vector3.zero;t.body.isKinematic=true;if(i<burialMounds.Length){burialMounds[i].SetPositionAndRotation(t.body.position+Vector3.down*.25f,Quaternion.Euler(0,t.body.rotation.eulerAngles.y,0));burialMounds[i].localScale=Vector3.one;}Announce(setup.players[i].name+" BURIED BY THE MOUNTAIN");continue;}
    rules.Progress(i,world.Progress(t.body.position));float rear=BodyRear(t);if(previousRear[i]<world.length&&rear>=world.length&&Mathf.Abs(t.body.position.x-world.finish.position.x)<35&&Mathf.Abs(t.body.position.y-world.finish.position.y)<10){float fraction=Mathf.Clamp01((world.length-previousRear[i])/Mathf.Max(.001f,rear-previousRear[i]));rules.Finish(i,before+fraction*dt);Announce(setup.players[i].name+" ESCAPED · #"+rules.Place(i));}
    else if(t.body.position.y<world.Height(t.body.position)-15||Mathf.Abs(t.body.position.x)>world.halfWidth+60){rules.Eliminate(i,"LOST IN THE RAVINE");fragments[i].Burst();t.Power(false);}
    else{t.tractorMotor.gripScale=atmosphere.Grip*(caught?.48f:.9f);var command=setup.players[i].source==BowlingSource.AI?Bot(i,dt):commands[i];t.TickDrive(command);stuckFor[i]=t.body.linearVelocity.magnitude<1?stuckFor[i]+dt:0;if((setup.players[i].released&&ActionHeld(i)||setup.players[i].source==BowlingSource.AI&&stuckFor[i]>4)&&rules.Clock>=recoverAt[i]&&(t.transform.up.y<.25f||stuckFor[i]>3))Recover(i);}
    previous[i]=t.body.position;previousRear[i]=rear;
   }
  }
  Vector2 Bot(int i,float dt){var t=trucks[i];float width=world.routes[route[i]].shortcut?Mathf.Lerp(15,3,Mathf.InverseLerp(150,350,t.body.position.z)):15;var goal=world.Target(route[i],t.body.position,ref segment[i],(i%4-1.5f)/1.5f*width);var points=world.routes[route[i]].points;float pace=1.45f;int at=segment[i];if(at+1<points.Length){float bend=Vector3.Angle(Vector3.ProjectOnPlane(points[at]-points[Mathf.Max(0,at-1)],Vector3.up),Vector3.ProjectOnPlane(points[at+1]-points[at],Vector3.up));float remaining=Vector3.ProjectOnPlane(goal-t.body.position,Vector3.up).magnitude;if(bend>12&&remaining<55)pace=Mathf.Lerp(.6f,1.45f,Mathf.InverseLerp(12,55,remaining));}float heading=Vector3.Angle(Vector3.ProjectOnPlane(t.transform.forward,Vector3.up),Vector3.ProjectOnPlane(goal-t.body.position,Vector3.up));if(heading>12)pace=Mathf.Min(pace,.7f);drivers[i].speedScale=pace;drivers[i].DirectGoal(t.body.position,goal);return drivers[i].Drive(t.body,t.transform,(int)setup.players[i].difficulty,dt,atmosphere.Grip);}
  void Recover(int i){var t=trucks[i];var points=world.routes[route[i]].points;int index=Mathf.Max(0,segment[i]-1);var p=points[index];if(p.z>t.body.position.z)p=previous[i]-Vector3.forward*8;p.y=Mathf.Max(world.Height(p),world.FrontHeight(p.z))+.65f;t.GetComponent<NWH.VehiclePhysics2.Damage.DamageHandler>()?.Repair();t.Prepare(p,Quaternion.LookRotation(points[Mathf.Min(index+1,points.Length-1)]-p));drivers[i].Reset();recoverAt[i]=rules.Clock+6;stuckFor[i]=0;previousRear[i]=BodyRear(t);}
  void Announce(string value){announcement=value;announcementUntil=rules.Clock+3;}
  protected override void Present(float dt){if(drivingViews==null)return;if(ReplayControls){review.Tick();return;}drivingViews.Tick(dt);if(drivingViews.NeedsArena){int focus=0;for(int i=1;i<setup.count;i++)if(rules.alive[i]&&!rules.finished[i]&&rules.distance[i]>rules.distance[focus])focus=i;var t=trucks[focus];broadcast.Pose(t.body.position+Vector3.forward*18,new Vector3(28,35,-45),70);}}
  public override void ExtraAction(string key){if(key=="drivingview")drivingViews.Cycle();else review?.Action(key);}protected override void SetPaused(bool pause){atmosphere?.Pause(pause);if(pause)front.rumble.Pause();else front.rumble.UnPause();}protected override void StopSounds(){if(trucks!=null)foreach(var t in trucks)t.StopSound();if(front!=null&&front.rumble!=null)front.rumble.Stop();}
  protected override void StopGame(){review?.End(false);StopSounds();if(front!=null){front.cloud.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);foreach(var rb in front.debris){if(!rb.isKinematic)rb.linearVelocity=rb.angularVelocity=Vector3.zero;rb.isKinematic=true;}}if(trucks!=null)foreach(var t in trucks){t.Power(false);if(!t.body.isKinematic)t.body.linearVelocity=t.body.angularVelocity=Vector3.zero;t.body.isKinematic=true;}}
 }
}
